chmod +x /tmp/cxx.sh && cat > /tmp/t2.cpp <<'EOF'
#include <cstdio>
#include <cstdint>
inline uint64_t low_mask(int len) {
    if (len <= 0) return 0;
    if (len >= 64) return ~0ULL;
    return (~0ULL << (64 - len));
}
inline uint64_t get_bits(uint64_t hi, uint64_t lo, int pos, int n) {
    if (n <= 0) return 0;
    if (pos + n <= 64) return (hi >> (64 - pos - n)) & low_mask(n);
    if (pos >= 64) return (lo >> (64 - (pos - 64) - n)) & low_mask(n);
    int hi_bits = 64 - pos;
    uint64_t value = (hi & low_mask(hi_bits)) << (n - hi_bits);
    value |= (lo >> (64 - (n - hi_bits))) & low_mask(n - hi_bits);
    return value;
}
int main(){
    uint64_t hi = 0x7311800000000000ULL;
    int rel = 1;
    uint64_t frag = get_bits(hi, 0, 16, rel) << (64 - rel);
    printf("frag=%016llx\n", (unsigned long long)frag);
    return 0;
}
EOF
/tmp/cxx.sh -std=c++14 -O0 /tmp/t2.cpp -o /tmp/t2 && /tmp/t2
